import math
import unittest

from solution import relax


class RelaxTests(unittest.TestCase):
    def test_updates_are_simultaneous(self):
        source = [0, 9, 0, 0]
        result = relax(source, 1)
        self.assertEqual(result, [0.0, 3.0, 3.0, 0.0])
        self.assertEqual(source, [0, 9, 0, 0])
        self.assertIsNot(result, source)
        self.assertEqual(relax(source, 2), [0.0, 2.0, 2.0, 0.0])

    def test_generator_zero_iterations_and_short_inputs(self):
        self.assertEqual(relax((x for x in [1, 2, 3]), 0), [1.0, 2.0, 3.0])
        empty = []
        self.assertEqual(relax(empty, 10), [])
        self.assertIsNot(relax(empty, 0), empty)
        self.assertEqual(relax([7], 4), [7.0])
        self.assertEqual(relax([1, 2], 4), [1.0, 2.0])

    def test_invalid_inputs(self):
        for values in (None, 3, "123", b"123"):
            with self.assertRaises(TypeError): relax(values, 1)
        for iterations in (True, 1.0, "1"):
            with self.assertRaises(TypeError): relax([], iterations)
        with self.assertRaises(ValueError): relax([], -1)
        for value in (True, "1", None):
            with self.assertRaises(TypeError): relax([value], 0)
        for value in (math.inf, -math.inf, math.nan):
            with self.assertRaises(ValueError): relax([value], 0)


if __name__ == "__main__":
    unittest.main()

